package com.typewritermc.authoring

/**
 * Marks declarations that exist for code generated by Typewriter codegen. Hand written code uses the generated typed
 * API for a declaration instead (XFields, XDraft, XPresentationScope and so on).
 */
@RequiresOptIn(
    level = RequiresOptIn.Level.ERROR,
    message = "Generated SDK hook. Use the API generated for your declaration instead.",
)
@Retention(AnnotationRetention.BINARY)
@Target(
    AnnotationTarget.CLASS,
    AnnotationTarget.FUNCTION,
    AnnotationTarget.PROPERTY,
    AnnotationTarget.CONSTRUCTOR,
    AnnotationTarget.TYPEALIAS,
)
annotation class GeneratedSdkApi
